int fun(int a, int b, int l, int r, vector<int>& flag, int& temp, int in_start, int in_end) {
    if ((r - l + 1) > 2 * (a + b))
        return (a <= b) ? a + 1 : (2 * a - b);

    int size = 3 * (a + b);
    // Initialize flag array
    for (int i = 1; i <= a; i++) {
        flag[i] = i;
        temp = i;
    }
    for (int i = a + 1; i <= a + b; i++) {
        flag[i] = temp;
    }
    for (int i = a + b + 1; i <= a + b + a; i++) {
        int tc = 1;
        while (in(flag, tc, a + b - a + 1, i - 1))
            tc++;
        flag[i] = tc;
        temp = flag[i];
    }
    for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
        flag[i] = temp;
    }
    for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
        flag[i] = flag[i - (a + b)];
    }

    int flagc[25] = {0};
    int templ = l % (a + b);
    if (templ == 0) templ += a + b;
    int tempr = r - l + templ;
    if (tempr < templ) tempr += a + b;
    for (int i = templ; i <= tempr; i++) {
