            flagc[flag[i]] = 1;
        }
    }

    int res = 0;
    for (int i = 1; i <= 24; i++)
        res += flagc[i];

    return res;
}

bool in(const vector<int>& a, int b, int l, int r) {
    for (int i = l; i <= r; i++) {
        if (a[i] == b)
            return true;
    }
    return false;
}

